import {supabase,currentUser,login} from './auth-client.mjs';
import {validateSubmission} from './admin-model.mjs';
import {supportHeads} from './farm-support-assets.mjs';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n},picture=(path,alt,cls)=>{const n=el('img',undefined,cls);n.src=new URL(path,import.meta.url);n.alt=alt;return n};let crops=[],rows=[],busy=false,selectedCrop=0,user=null,revision=0;const revealed=new Map();let currentCycle=Math.floor(Date.now()/43200000);
async function rpc(name,args={}){const {data,error}=await supabase.rpc(name,args);if(error)throw Error(error.message);return data}
function status(text){$('farm-status').textContent=text;if($('farm-submit-dialog').open)$('submit-status').textContent=text}
function filters(){const all=el('button','All fruits');all.type='button';all.setAttribute('aria-pressed',String(selectedCrop===0));all.onclick=()=>{selectedCrop=0;filters();render()};$('fruit-filters').replaceChildren(all,...crops.map(c=>{const b=el('button');b.type='button';b.title=c.name;b.setAttribute('aria-label',c.name);b.setAttribute('aria-pressed',String(selectedCrop===c.id));b.append(picture('.'+c.icon,'',''));b.onclick=()=>{selectedCrop=c.id;filters();render()};return b}))}
function render(){const shown=rows.filter(r=>(!selectedCrop||r.crop_id===selectedCrop)&&Number(r.exhausted)<3);$('farm-list').replaceChildren(...shown.map(r=>{const crop=crops.find(c=>c.id===r.crop_id),card=el('article',undefined,'farm-row');card.setAttribute('aria-label',crop.support+' · '+crop.name+' · +'+r.bonus+'%');card.append(picture('./tatari-data/'+supportHeads[crop.support],crop.support,'farm-head'),picture('.'+crop.icon,crop.name,'farm-fruit'),el('strong','+'+r.bonus+'%','farm-value'));const feedback=el('div',undefined,'farm-feedback');for(const [label,value,count] of [['Working','worked',r.worked],['Not Working','not_working',r.not_working],['Exhausted','exhausted',r.exhausted]]){const b=el('button',label+' '+Number(count||0),'btn secondary');b.type='button';b.disabled=!revealed.has(r.id);b.title=b.disabled?'Connect before leaving feedback':label;b.onclick=async()=>{b.disabled=true;try{await rpc('report_farm_support',{p_id:r.id,p_report:value});await reload();status('Feedback saved for this 12-hour round.')}catch(e){status(e.message);b.disabled=false}};feedback.append(b)}const connect=el('button','Connect','btn farm-connect');connect.type='button';connect.onclick=async()=>{connect.disabled=true;try{const uid=await rpc('reveal_farm_support',{p_id:r.id});revealed.set(r.id,uid);await reload();try{await navigator.clipboard.writeText(uid);status('UID copied. Use it in Cozy Farm to connect.')}catch{status('UID revealed below. Copy it to connect in Cozy Farm.')}}catch(e){status(e.message)}finally{connect.disabled=false}};card.append(feedback,connect);if(revealed.has(r.id)){const line=el('p','UID '+revealed.get(r.id),'revealed'),copy=el('button','Copy UID');copy.type='button';copy.onclick=()=>navigator.clipboard.writeText(revealed.get(r.id)).then(()=>status('UID copied.')).catch(()=>status('Select the displayed UID to copy it.'));line.append(copy);card.append(line)}return card}));if(!shown.length)$('farm-list').append(el('p','No reviewed support is available for this fruit yet.','farm-empty'))}
async function reload(){const cycle=Math.floor(Date.now()/43200000);if(cycle!==currentCycle){currentCycle=cycle;revealed.clear()}rows=await rpc('farm_support_directory');render();const requests=await rpc('my_farm_support_requests');$('my-submissions').replaceChildren(...requests.map(r=>el('li','UID '+r.game_uid+' · '+crops.find(c=>c.id===r.crop_id)?.name+' · +'+r.bonus+'% · '+r.status+(r.review_note?' · '+r.review_note:''))));if(!requests.length)$('my-submissions').append(el('li','No submissions yet.'))}
async function gate(){const token=++revision;user=await currentUser();if(token!==revision)return;$('farm-tools').hidden=!user;$('farm-gate').hidden=!!user;revealed.clear();if(user)try{await reload();status('Select a fruit to find support.')}catch(e){status('Could not load the support directory. '+e.message)}else status('Sign in to use the support directory.')}
$('farm-login').onclick=()=>login('discord').catch(e=>status(e.message));$('open-submit').onclick=()=>{if(!user){status('Sign in before submitting a UID.');$('farm-login').focus();return}if(selectedCrop)$('submit-crop').value=selectedCrop;$('submit-status').textContent='Submissions are reviewed before appearing publicly.';$('farm-submit-dialog').showModal()};$('close-submit').onclick=()=>$('farm-submit-dialog').close();
$('farm-submit').onsubmit=async e=>{e.preventDefault();if(busy)return;try{const v=validateSubmission({uid:$('submit-uid').value.trim(),crop:Number($('submit-crop').value),bonus:Number($('submit-bonus').value),permission:$('submit-permission').checked,note:$('submit-note').value});busy=true;$('submit-button').disabled=true;await rpc('submit_farm_support',{p_uid:v.uid,p_crop:v.crop,p_bonus:v.bonus,p_permission:v.permission,p_note:v.note});$('farm-submit').reset();await reload();status('Submitted for review. It is not public yet.')}catch(e){status(e.message)}finally{busy=false;$('submit-button').disabled=false}};
try{const response=await fetch(new URL('./guide-data/cozy-farm.json',import.meta.url));if(!response.ok)throw Error('Fruit data unavailable');crops=(await response.json()).crops;$('submit-crop').replaceChildren(...crops.map(c=>{const n=el('option',c.name);n.value=c.id;return n}));filters();await gate()}catch(e){status(e.message)}supabase.auth.onAuthStateChange(()=>setTimeout(()=>gate().catch(e=>status(e.message)),0));
